        pending=FALSE,force_write=FALSE,failures=0,error_code=NULL,next_at=0,tenant_id=#{tenant},workspace_id=#{space},subject_id=#{subject},conversation_id=#{conv},owner_key=#{owner}
        WHERE generation=#{g} AND task_key=#{task}

UPDATE arte_ai_search_entry SET
        identity_json=#{r.identityJson},fingerprint=#{r.fingerprint},revision=#{r.revision},desired=#{r.desired} WHERE
        generation=#{g} AND entry_key=#{r.entryKey}

